// Mastered copies of the supplied recordings. Original assets remain in place.
window.HEAL_MASTERED_AUDIO = {"hover":"","mouseclick":"","exhaust":"","microwave":"","water":"","rice":"","irrigator":"","plastic":"","alert":""};
// Shared output protection for overlapping voices, including direct-file playback.
window.HEALMaster = (() => {
  const buses = new WeakMap();
  const mediaSources = new WeakMap();
  let mediaContext;
  function bus(context) {
    if (buses.has(context)) return buses.get(context);
    const limiter = context.createDynamicsCompressor();
    limiter.threshold.value = -9;
    limiter.knee.value = 0;
    limiter.ratio.value = 20;
    limiter.attack.value = 0.002;
    limiter.release.value = 0.12;
    const headroom = context.createGain();
    headroom.gain.value = 0.9;
    limiter.connect(headroom).connect(context.destination);
    buses.set(context, limiter);
    return limiter;
  }
  function url(key) { return 'data:audio/wav;base64,' + window.HEAL_MASTERED_AUDIO[key]; }
  function context() {
    mediaContext ||= new (window.AudioContext || window.webkitAudioContext)();
    return mediaContext;
  }
  function play(audio) {
    context();
    if (!mediaSources.has(audio)) {
      const source = mediaContext.createMediaElementSource(audio);
      source.connect(bus(mediaContext));
      mediaSources.set(audio, source);
    }
    if (mediaContext.state === 'suspended') mediaContext.resume().catch(() => {});
    return audio.play();
  }
  return { bus, url, play, context };
})();
